    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best-Fit principle: minimize remaining space)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to how much we could have fit elsewhere
    // We increase this penalty as we progress through the stream to encourage consolidation
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 + progress);
        } else {
            // If no other bin fits, this is forced; prioritize lowest cost for unavoidable new bins
            score = 0.0;
        }
    } else {
        // Reward filling bins that are already "below average" to keep distribution tight
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
