            if post_residual < next_item_size {
                // Potential "dead space" penalty
                score += (next_item_size - post_residual) as f64 * 1.5;
            } else {
                // "Lookahead bonus": reward leaving space for the next item
                score -= (next_item_size as f64) * 0.8;
