        score += 25.0;
    }

    // 3. Prefer filling the most "tight" bins first (Best Fit).
    // Penalize bins that have a large residual relative to the average.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // 4. Threshold for opening a new bin:
    // Only open a new bin if the current fit is very poor (post_residual > 30)
    // and we are not near the end of the stream.
