pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We prefer small post_residuals, but not so small that they trap the bin
    // into being unusable for the next incoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 50.0 * (1.0 - progress);
        }
    }

    // 2. Thresholding for New Bins:
    // If the bin is new (bin_residual == bin_capacity), we penalize opening it
    // based on how many existing bins could have fit this item.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += (fitting_bins_count as f64) * 15.0;
        // As the stream progresses, we become more conservative about opening new bins.
        score += (progress * 40.0);
    } else {
        // 3. Balancing existing bins:
        // Prefer bins where the post_residual is closer to the mean_residual
        // to keep bin utilization uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Lookahead optimization:
    // If we have a very large item coming next, prioritize bins that can accommodate it.
    if next_item_size > 60 && post_residual < next_item_size {
        score += 30.0;
    }

    // 5. Final constraint: Avoid "orphaning" small space that cannot fit typical items (10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}
